"""Render every lesson figure from the same JavaScript used by the course."""
from pathlib import Path
import json

def render(root: Path):
    course=json.dumps(json.loads((root/'course.json').read_text()),ensure_ascii=False).replace('</','<\\/')
    drawings=(root/'visuals.js').read_text()+'\n'+(root/'visual-lessons.js').read_text()
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Visual companion — Common Ground</title><!--
__RIGHTS_NOTICES__
--><style>__FONTS__
*{box-sizing:border-box}body{margin:0;background:#EDF3F8;color:#19394D;font:17px/1.75 CourseSans,Arial,sans-serif}main{max-width:1180px;margin:auto;padding:35px 28px 70px}h1,h2,h3{font-family:CourseSerif,Georgia,serif;font-weight:400;line-height:1.3}h1{font-size:46px;letter-spacing:-1px;margin:25px 0}h2{font-size:31px;margin:40px 0 25px}h3{font-size:23px;margin:0 0 18px}a{color:#216B88;text-underline-offset:4px}a:focus-visible,button:focus-visible{outline:3px solid #A1486D;outline-offset:4px}button{font:inherit;padding:9px 16px;border:1px solid #8DA6B7;border-radius:6px;background:white;color:#19394D;cursor:pointer}.guide-actions{display:flex;gap:20px;align-items:center;flex-wrap:wrap}.intro{max-width:720px;color:#4B6172}.contents{display:grid;grid-template-columns:1fr 1fr;gap:8px 35px;padding:0;list-style:none}.visual-grid{display:grid;grid-template-columns:1fr 1fr;gap:30px}.visual-card{margin:0;border-top:1px solid #B9CDD9;padding:25px 0;break-inside:avoid}.visual-card svg{display:block;background:#E4EEF3;width:100%;height:auto;max-height:500px}.visual-card figcaption{font-size:16px;color:#4B6172;margin-top:16px;line-height:1.75}.figure-chapter{font-size:13px;color:#4B6172;margin:0 0 12px}.print-tip{font-size:14px;color:#4B6172}svg text{font-family:CourseSans,Arial,sans-serif}@media(max-width:700px){main{padding:22px 20px 45px}.visual-grid,.contents{grid-template-columns:1fr}h1{font-size:35px}h2{font-size:27px}.visual-card h3{font-size:22px}.guide-actions{gap:12px;font-size:15px}}@page{size:A4;margin:16mm}@media print{html,body{background:white;print-color-adjust:exact;-webkit-print-color-adjust:exact}main{padding:0;max-width:none}.guide-actions,nav,.print-tip{display:none}.cover{break-after:page;padding-top:35mm}.cover h1{font-size:34pt}.cover p{font-size:13pt}.visual-grid{display:block}.visual-chapter>h2{display:none}.visual-card{height:257mm;padding:0;border:0;break-after:page;break-inside:avoid}.visual-card h3{font-size:21pt;line-height:1.3;margin-bottom:8mm}.visual-card svg{height:auto;width:100%;max-height:174mm}.visual-card figcaption{font-size:11pt;line-height:1.6;margin-top:6mm}.figure-chapter{font-size:10pt;margin-bottom:5mm}}
</style></head><body><main id="guide"></main><script>
const COURSE='''+course+''';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
'''+drawings+'''
const allViews=COURSE.flatMap(c=>c.slides.flatMap(s=>(visualLessons[s.id]||[]).map(v=>({c,s,v}))));
document.querySelector('#guide').innerHTML=`<header class="cover"><div class="guide-actions"><a href="index.html">Common Ground · Back to the course</a><button onclick="window.print()">Print visual companion</button><a href="visual-guide.pdf" download>Download PDF</a></div><h1>Common Ground<br>Visual companion</h1><p class="intro">Explore every teaching concept through original diagrams and fictional café examples. Each caption explains the idea and its limits.</p><p class="intro">${allViews.length} visual explanations across ten chapters. The chapter slides show the main figure, with additional views under “More visual explanations.” This companion brings every view together for reading and printing.</p><p class="print-tip">The PDF gives each figure its own page. These illustrations support the course explanations and evidence notes; they do not replace the relevant research or practical training.</p></header><nav aria-label="Visual chapters"><ul class="contents">${COURSE.map(c=>`<li><a href="#chapter-${c.number}">${c.number}. ${esc(c.title)}</a></li>`).join('')}</ul></nav>${COURSE.map(c=>`<section class="visual-chapter" id="chapter-${c.number}"><h2>${c.number}. ${esc(c.title)}</h2><div class="visual-grid">${c.slides.flatMap(s=>(visualLessons[s.id]||[]).map(v=>`<figure class="visual-card" id="${v.key}"><p class="figure-chapter">Chapter ${c.number} · ${esc(c.title)}</p><h3>${esc(v.title)}</h3>${v.render()}<figcaption>${esc(v.caption)}</figcaption></figure>`)).join('')}</div></section>`).join('')}`;
</script></body></html>'''
